mapper.select:
SELECT aie.id, aie.event_id, aie.change_kind, aie.impacted_user_count, aie.version_bumped_count, aie.profile_refreshed_count, aie.profile_evicted_count, aie.processed_at, aie.created_at, aie.updated_at, aie.created_by, aie.updated_by FROM auth_authorization_invalidation_event aie
AND aie.event_id LIKE CONCAT(#{query.eventId}, '%')
AND aie.change_kind = #{query.changeKind}
AND aie.impacted_user_count = -1
AND aie.impacted_user_count != -1
AND aie.processed_at > = #{query.processedAtStart}
AND aie.processed_at < = #{query.processedAtEnd}
ORDER BY aie.processed_at DESC, aie.created_at DESC

mapper.delete:
DELETE
FROM auth_authorization_invalidation_event
WHERE impacted_user_count = -1
  AND updated_at < #{cutoffTime}
LIMIT #{batchSize}

DELETE
FROM auth_authorization_invalidation_event
WHERE impacted_user_count != -1
  AND processed_at IS NOT NULL
  AND processed_at < #{cutoffTime}
LIMIT #{batchSize}
